I'll create a focused Terraform module for the three resources (S3, RDS, IAM) with dev/prod separation via tfvars. Here's the complete structure.

## Directory Layout

```
.
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── providers.tf
├── dev.tfvars
└── prod.tfvars
```

---

## `modules/app-infra/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}
```

---

## `modules/app-infra/variables.tf`

```hcl
variable "environment" {
  description = "Environment name (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "name_prefix" {
  description = "Prefix for all resource names"
  type        = string
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---------- S3 ----------
variable "bucket_name" {
  description = "Base name of the application assets bucket (must be globally unique-ish; suffix added)"
  type        = string
}

variable "enable_replication" {
  description = "Enable cross-region replication (prod)"
  type        = bool
  default     = false
}

variable "replication_region" {
  description = "Destination region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

# ---------- RDS ----------
variable "db_name" {
  description = "Initial PostgreSQL database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master DB username"
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "Master DB password (pass via -var-file / SOPS, never commit)"
  type        = string
  sensitive   = true
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_multi_az" {
  description = "Enable Multi-AZ (prod)"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Encrypt RDS storage at rest"
  type        = bool
  default     = true
}

variable "backup_retention_days" {
  description = "Backup retention (>= 7 per policy)"
  type        = number
  default     = 7
  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "backup_retention_days must be >= 7."
  }
}

variable "db_subnet_ids" {
  description = "Private subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "vpc_id" {
  description = "VPC ID for the DB security group"
  type        = string
}

variable "db_ingress_cidrs" {
  description = "CIDR blocks allowed to reach the DB (private only)"
  type        = list(string)
  default     = []
}

# ---------- IAM ----------
variable "oidc_provider_arn" {
  description = "EKS/IRSA OIDC provider ARN for role trust (prod least-privilege)"
  type        = string
  default     = ""
}

variable "oidc_provider_url" {
  description = "OIDC provider URL (without https://)"
  type        = string
  default     = ""
}

variable "service_account_namespace" {
  description = "K8s namespace of the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "K8s service account name for IRSA"
  type        = string
  default     = "app-sa"
}
```

---

## `modules/app-infra/main.tf`

```hcl
locals {
  is_prod = var.environment == "prod"
  name    = "${var.name_prefix}-${var.environment}"
  tags    = merge(var.tags, { Environment = var.environment, ManagedBy = "terraform" })
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

#############################################
# S3 - Application assets bucket
#############################################
resource "aws_s3_bucket" "assets" {
  bucket = "${var.bucket_name}-${var.environment}-${random_id.bucket_suffix.hex}"
  tags   = local.tags
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---- Cross-region replication (prod only) ----
resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = "${var.bucket_name}-${var.environment}-replica-${random_id.bucket_suffix.hex}"
  tags     = local.tags
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.name}-s3-replication"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.name}-s3-replication"
  role  = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [aws_s3_bucket.assets.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = ["${aws_s3_bucket.assets.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = ["${aws_s3_bucket.replica[0].arn}/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count      = var.enable_replication ? 1 : 0
  depends_on = [aws_s3_bucket_versioning.assets]
  bucket     = aws_s3_bucket.assets.id
  role       = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }
}

#############################################
# RDS - PostgreSQL
#############################################
resource "aws_db_subnet_group" "this" {
  name       = "${local.name}-db-subnets"
  subnet_ids = var.db_subnet_ids
  tags       = local.tags
}

resource "aws_security_group" "db" {
  name        = "${local.name}-db-sg"
  description = "DB access - private only"
  vpc_id      = var.vpc_id

  ingress {
    description = "PostgreSQL from allowed CIDRs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.db_ingress_cidrs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.tags
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name}-postgres"
  engine         = "postgres"
  engine_version = "16"
  instance_class = var.db_instance_class

  allocated_storage = var.db_allocated_storage
  storage_encrypted = var.db_storage_encrypted
  storage_type      = "gp3"

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]

  multi_az            = var.db_multi_az
  publicly_accessible = false

  backup_retention_period = var.backup_retention_days
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${local.name}-postgres-final"

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  tags = local.tags
}

#############################################
# IAM - service account role
#############################################

# Prod: IRSA / OIDC trust with least privilege
data "aws_iam_policy_document" "irsa_trust" {
  count = var.oidc_provider_arn != "" ? 1 : 0
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

# Dev fallback: EC2 assume (or leave generic) when no OIDC provided
data "aws_iam_policy_document" "svc_trust" {
  count = var.oidc_provider_arn == "" ? 1 : 0
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "service" {
  name = "${local.name}-service-role"
  assume_role_policy = var.oidc_provider_arn != "" ? data.aws_iam_policy_document.irsa_trust[0].json : data.aws_iam_policy_document.svc_trust[0].json
  tags = local.tags
}

# Least-privilege access to the specific bucket only.
# Note: no wildcard actions.
data "aws_iam_policy_document" "service_policy" {
  statement {
    sid    = "BucketList"
    effect = "Allow"
    actions = ["s3:ListBucket"]
    resources = [aws_s3_bucket.assets.arn]
  }
  statement {
    sid    = "ObjectRW"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }
}

resource "aws_iam_policy" "service" {
  name   = "${local.name}-service-policy"
  policy = data.aws_iam_policy_document.service_policy.json
  tags   = local.tags
}

resource "aws_iam_role_policy_attachment" "service" {
  role       = aws_iam_role.service.name
  policy_arn = aws_iam_policy.service.arn
}

# Dev-only: IAM user with programmatic access
resource "aws_iam_user" "service" {
  count = local.is_prod ? 0 : 1
  name  = "${local.name}-service-user"
  tags  = local.tags
}

resource "aws_iam_user_policy_attachment" "service" {
  count      = local.is_prod ? 0 : 1
  user       = aws_iam_user.service[0].name
  policy_arn = aws_iam_policy.service.arn
}

resource "aws_iam_access_key" "service" {
  count = local.is_prod ? 0 : 1
  user  = aws_iam_user.service[0].name
}
```

The module needs the aliased replica provider passed in:

```hcl
# add to modules/app-infra/versions.tf providers block requirement
# (configuration_aliases so root passes aws.replica)
```

Add to `modules/app-infra/versions.tf` inside the `aws` provider block:

```hcl
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.0"
      configuration_aliases = [aws.replica]
    }
```

---

## `modules/app-infra/outputs.tf`

```hcl
output "bucket_name" {
  value = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  value = var.enable_replication ? aws_s3_bucket.replica[0].id : null
}

output "db_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

output "db_port" {
  value = aws_db_instance.postgres.port
}

output "service_role_arn" {
  value = aws_iam_role.service.arn
}

output "service_user_access_key_id" {
  value     = local.is_prod ? null : aws_iam_access_key.service[0].id
  sensitive = true
}

output "service_user_secret_access_key" {
  value     = local.is_prod ? null : aws_iam_access_key.service[0].secret
  sensitive = true
}
```

---

## Root `providers.tf`

```hcl
provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = var.replication_region
}
```

---

## Root `variables.tf`

```hcl
variable "region" {
  type    = string
  default = "us-east-1"
}

variable "replication_region" {
  type    = string
  default = "us-west-2"
}

variable "environment" { type = string }
variable "name_prefix" { type = string }

variable "bucket_name"        { type = string }
variable "enable_replication" { type = bool }

variable "db_instance_class"     { type = string }
variable "db_multi_az"           { type = bool }
variable "db_storage_encrypted"  { type = bool }
variable "backup_retention_days" { type = number }
variable "db_password"           { type = string, sensitive = true }

variable "db_subnet_ids" { type = list(string) }
variable "vpc_id"        { type = string }
variable "db_ingress_cidrs" { type = list(string) }

variable "oidc_provider_arn" { type = string, default = "" }
variable "oidc_provider_url" { type = string, default = "" }
```

---

## Root `main.tf`

```hcl
terraform {
  required_version = ">= 1.5"
  # Recommended: separate state per environment.
  # Use workspaces OR distinct backend keys per env.
  backend "s3" {
    bucket = "my-tfstate-bucket"
    key    = "app-infra/terraform.tfstate" # override per env via -backend-config
    region = "us-east-1"
  }
}

module "app_infra" {
  source = "./modules/app-infra"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment = var.environment
  name_prefix = var.name_prefix

  bucket_name        = var.bucket_name
  enable_replication = var.enable_replication
  replication_region = var.replication_region

  db_instance_class     = var.db_instance_class
  db_multi_az           = var.db_multi_az
  db_storage_encrypted  = var.db_storage_encrypted
  backup_retention_days = var.backup_retention_days
  db_password           = var.db_password

  db_subnet_ids    = var.db_subnet_ids
  vpc_id           = var.vpc_id
  db_ingress_cidrs = var.db_ingress_cidrs

  oidc_provider_arn = var.oidc_provider_arn
  oidc_provider_url = var.oidc_provider_url

  tags = {
    Project = "canonical-scenario"
  }
}
```

---

## Root `outputs.tf`

```hcl
output "bucket_name"      { value = module.app_infra.bucket_name }
output "db_endpoint"      { value = module.app_infra.db_endpoint }
output "service_role_arn" { value = module.app_infra.service_role_arn }
```

